import{_ as o}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as i,c as s,o as e,af as a,b as l,w as r,a as d,G as h,ag as c}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const T=JSON.parse('{"title":"组 2 · 推理与接口","description":"从 prefill/decode 两阶段到用户可见接口的一条线——延迟与成本的物理结构、serving 降本机制，以及 API 契约、结构化输出、流式、生成式 UI、端侧接入七个主题的组导览。","frontmatter":{"title":"组 2 · 推理与接口","description":"从 prefill/decode 两阶段到用户可见接口的一条线——延迟与成本的物理结构、serving 降本机制，以及 API 契约、结构化输出、流式、生成式 UI、端侧接入七个主题的组导览。","domain":"tech","tags":["inference","interface","navigation"],"navOrder":19,"topicId":"integration","layer":"2","status":"canonical","nodeType":"problem","owner":"learn-ai","prerequisites":["model-lifecycle-bridge"],"next":["model-api","streaming","session-state"],"lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"zh/tech/02-inference-interface/index.md","filePath":"zh/tech/02-inference-interface/index.md","lastUpdated":1791117695000}'),u={name:"zh/tech/02-inference-interface/index.md"};function p(m,t,g,f,E,b){const n=i("Mermaid");return e(),s("div",null,[t[1]||(t[1]=a('<h1 id="组-2-·-推理与接口" tabindex="-1">组 2 · 推理与接口 <a class="header-anchor" href="#组-2-·-推理与接口" aria-label="Permalink to &quot;组 2 · 推理与接口&quot;">​</a></h1><blockquote><p><strong>所在组</strong>：组 2 · 推理与接口 ｜ <strong>上一组出口</strong>：能说出模型生命周期如何影响工程决策（模型是可替换的外部能力，带行为、预算、能力边界三个接口属性） ｜ <strong>本组出口</strong>：能交付一次可归因（延迟拆得开段）、可观测（usage 看得见）、可取消的用户可见交互 <strong>前置</strong>：<a href="./../01-model-lifecycle/">模型生命周期（桥接）</a> ｜ <strong>下一步</strong>：<a href="./../03-context/session-memory.html">会话与状态</a>、<a href="./../04-grounding/rag.html">嵌入与检索</a></p></blockquote><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p>本组回答一个问题：<strong>参数如何变成在线服务与契约？</strong> 它是一条从 prefill/decode 两阶段生成一直接到用户可见接口的线——前半段解释延迟与成本从哪来（你拿到的 TTFT 和账单不是玄学，是流水线的输出），后半段把模型能力接成产品交互（调用契约、输出形态、呈现节奏、接入位置）。</p><p>这条线此前缺了前半段：只学&quot;怎么调 API&quot;的工程师解释不了首字为什么慢、cached input 为什么便宜、什么时候该自建 serving。本组用七个主题补全：</p><ul><li><strong>服务侧</strong>（模型发生了什么）：<a href="./inference-fundamentals.html">推理基础</a> 拆延迟结构，<a href="./efficient-serving.html">高效服务</a> 拆成本结构。</li><li><strong>接口侧</strong>（你怎么接）：<a href="./model-api.html">模型 API 契约</a> 稳住调用，<a href="./structured-output.html">结构化输出</a> 稳住形态，<a href="./streaming.html">流式响应</a> 稳住节奏，<a href="./ui.html">生成式 UI</a> 升级呈现，<a href="./browser-edge.html">浏览器与端侧推理</a> 换接入位置。</li></ul>',6)),(e(),l(c,null,{default:r(()=>[h(n,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%E6%A8%A1%E5%9E%8B%E7%94%9F%E5%91%BD%E5%91%A8%E6%9C%9F%3Cbr%2F%3E%EF%BC%88%E7%BB%84%201%20%E6%A1%A5%E6%8E%A5%E5%87%BA%E5%8F%A3%EF%BC%89%5D%20--%3E%20B%5Binference-fundamentals%3Cbr%2F%3E%E5%BB%B6%E8%BF%9F%E7%BB%93%E6%9E%84%5D%0A%20%20%20%20B%20--%3E%20C%5Befficient-serving%3Cbr%2F%3E%E6%88%90%E6%9C%AC%E6%9C%BA%E5%88%B6%5D%0A%20%20%20%20C%20--%3E%20D%5Bmodel-api%3Cbr%2F%3E%E8%B0%83%E7%94%A8%E5%A5%91%E7%BA%A6%5D%0A%20%20%20%20D%20--%3E%20E%5Bstructured-output%3Cbr%2F%3E%E8%BE%93%E5%87%BA%E5%BD%A2%E6%80%81%5D%0A%20%20%20%20E%20--%3E%20F%5Bstreaming%3Cbr%2F%3E%E5%91%88%E7%8E%B0%E8%8A%82%E5%A5%8F%5D%0A%20%20%20%20F%20--%3E%20G%5Bui%20%E7%BB%93%E6%9E%84%E5%8C%96%E7%95%8C%E9%9D%A2%5D%0A%20%20%20%20D%20--%3E%20H%5Bbrowser-edge%20%E7%AB%AF%E4%BE%A7%E6%8E%A5%E5%85%A5%5D%0A%20%20%20%20G%20--%3E%20I%5B%E6%9C%AC%E7%BB%84%E5%87%BA%E5%8F%A3%EF%BC%9A%E5%8F%AF%E5%BD%92%E5%9B%A0%E3%80%81%E5%8F%AF%E8%A7%82%E6%B5%8B%E3%80%81%E5%8F%AF%E5%8F%96%E6%B6%88%E7%9A%84%E4%BA%A4%E4%BA%92%5D%0A%20%20%20%20H%20--%3E%20I%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a(`<h3 id="何时进入本组-何时不进" tabindex="-1">何时进入本组 / 何时不进 <a class="header-anchor" href="#何时进入本组-何时不进" aria-label="Permalink to &quot;何时进入本组 / 何时不进&quot;">​</a></h3><ul><li><strong>进</strong>：要用模型造产品——先读前两页建立延迟与成本的心智模型，再进接口侧；或已在维护 AI 功能，需要归因延迟与成本。</li><li><strong>不进</strong>：训练与注意力的数学——回 <a href="./../01-model-lifecycle/">模型生命周期（桥接）</a> 的 Learn LLM 链；回答缺少私有事实——去 <a href="./../04-grounding/rag.html">嵌入与检索</a>；要让系统执行动作——去 <a href="./../05-action/tool-calling.html">工具调用契约</a>。</li></ul><h3 id="症状-→-主题导航" tabindex="-1">症状 → 主题导航 <a class="header-anchor" href="#症状-→-主题导航" aria-label="Permalink to &quot;症状 → 主题导航&quot;">​</a></h3><table tabindex="0"><thead><tr><th>症状</th><th>去哪</th><th>读完你能</th></tr></thead><tbody><tr><td>说不清首字为什么慢、账单为什么涨</td><td><a href="./inference-fundamentals.html">推理基础</a></td><td>把一次延迟拆进排队 / prefill / decode / 网络四段并归因</td></tr><tr><td>看不懂 cached input 一个价、普通 input 一个价</td><td><a href="./efficient-serving.html">高效服务</a></td><td>把量化和前缀缓存映射到计费字段，改造 prompt 与会话结构</td></tr><tr><td>第一条请求还没发出去 / 429 一来就崩</td><td><a href="./model-api.html">模型 API 契约</a></td><td>写出带错误族分类与重试的调用循环</td></tr><tr><td>回答稳定但没法进程序（解析靠正则）</td><td><a href="./structured-output.html">结构化输出</a></td><td>用 schema 约束并校验模型输出</td></tr><tr><td>接口通了，UI 要等整段才出字</td><td><a href="./streaming.html">流式响应</a></td><td>消费 SSE 流，可取消、可中断恢复</td></tr><tr><td>想让回答带组件而不只是文字</td><td><a href="./ui.html">生成式 UI</a></td><td>把模型输出渲染成白名单组件</td></tr><tr><td>想降延迟 / 保隐私 / 离线可用</td><td><a href="./browser-edge.html">浏览器与端侧推理</a></td><td>选对端侧运行库与降级链</td></tr></tbody></table><h3 id="决策表-接口侧的接入方式" tabindex="-1">决策表：接口侧的接入方式 <a class="header-anchor" href="#决策表-接口侧的接入方式" aria-label="Permalink to &quot;决策表：接口侧的接入方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>方向</th><th>控制权</th><th>状态</th><th>信任域</th><th>最低复杂度</th></tr></thead><tbody><tr><td>直接 fetch 厂商 API</td><td>出站请求/响应</td><td>全部自管</td><td>无（每轮自建）</td><td>密钥在服务端</td><td>单文件可跑</td></tr><tr><td>官方 SDK</td><td>出站请求/响应</td><td>SDK 管重试与类型</td><td>无</td><td>密钥在服务端</td><td>+1 依赖</td></tr><tr><td>前端 AI 框架</td><td>请求+流+UI 全包</td><td>框架接管</td><td>框架会话模型</td><td>密钥在服务端</td><td>引入框架契约</td></tr><tr><td>端侧推理</td><td>设备内执行</td><td>完全自管</td><td>设备本地</td><td>数据不出设备</td><td>模型分发+运行时</td></tr></tbody></table><p>服务侧的形态决策（API / 自建 serving / 端侧）见 <a href="./inference-fundamentals.html">推理基础</a> 的决策表。选型原则一致：<strong>从最低复杂度起步</strong>，被卡住再加层。</p><h3 id="历史版本里程碑" tabindex="-1">历史版本里程碑 <a class="header-anchor" href="#历史版本里程碑" aria-label="Permalink to &quot;历史版本里程碑&quot;">​</a></h3><p>厂商 API 形态持续演化（如 OpenAI 从 Chat Completions 到 Responses API、Anthropic 采样参数随模型世代收缩、两家先后上线前缀缓存）。本组不维护厂商时间线，具体字段以官方文档当天页面为准；本仓记录的决策影响断言均标注 retrievedAt。本页于 2026-09 随 Issue #116 从 v5&quot;应用接入&quot;层导览改写为 v6&quot;推理与接口&quot;组导览。</p><h2 id="_2-使用" tabindex="-1">2. 使用 <a class="header-anchor" href="#_2-使用" aria-label="Permalink to &quot;2. 使用&quot;">​</a></h2><p>本组最小实战是 <a href="./inference-fundamentals.html">推理基础</a> 的零 key 两阶段模拟器：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 保存该页完整示例为 inference-sim.mts，然后：</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inference-sim.mts</span></span></code></pre></div><p>验收：三段输出齐全——有 KV cache 的成本结构、无 cache 的负例（TTFT 相同、decode 放大 12 倍）、节省百分比。跑通后你已经亲手验证了&quot;prompt 打 TTFT、输出打总时长&quot;这条归因规则。</p><p>成本侧对应 <a href="./efficient-serving.html">高效服务</a> 的前缀缓存计算器（命中 / 未命中 / 低于最短长度三个场景）。组内各主题的使用段遵循同一约束：零 API key、单文件自包含、确定性输出、正常路径与负例路径成对出现。</p><h2 id="_3-原理" tabindex="-1">3. 原理 <a class="header-anchor" href="#_3-原理" aria-label="Permalink to &quot;3. 原理&quot;">​</a></h2><p>在能力变换链上，本组把&quot;一个可替换的外部能力&quot;变成&quot;一条可运营的交互链&quot;：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户动作 → 请求组装（结构化输出 schema + 会话状态）</span></span>
<span class="line"><span>        → serving（推理基础：排队/prefill/decode；高效服务：缓存与量化）</span></span>
<span class="line"><span>        → API 调用（model-api：错误族、重试、用量）</span></span>
<span class="line"><span>        → 流式呈现（streaming：SSE、累积、取消）</span></span>
<span class="line"><span>        → 结构化渲染（ui：白名单组件）</span></span></code></pre></div><ul><li><strong>不变量 1</strong>：模型 API 无状态。每次请求重发全部所需历史；&quot;对话记忆&quot;是接入层的构造物（→ <a href="./../03-context/session-memory.html">会话与状态</a>）。</li><li><strong>不变量 2</strong>：模型输出是不可信输入。渲染前必须过 schema 与白名单。</li><li><strong>不变量 3</strong>：交互必须可取消、可观测。取消依赖 AbortController 贯通到服务端停止生成；观测依赖 usage（含缓存命中字段）贯通到成本面板。</li><li><strong>不变量 4</strong>：延迟与成本可归因。TTFT、ITL、输入输出 token、缓存命中分开埋点——拆不开就无法优化。</li></ul><p><strong>出口标准（Exit criteria）</strong>：能交付一次可归因（延迟拆得开段）、可观测（usage 与命中率看得见）、可取消（中途可停、停后状态一致）的用户可见交互。</p><h2 id="_4-开发" tabindex="-1">4. 开发 <a class="header-anchor" href="#_4-开发" aria-label="Permalink to &quot;4. 开发&quot;">​</a></h2><p>进入接口侧前，先用三条诊断定位该读哪页。</p><h3 id="症状-→-证据-→-处理-→-完成标准" tabindex="-1">症状 → 证据 → 处理 → 完成标准 <a class="header-anchor" href="#症状-→-证据-→-处理-→-完成标准" aria-label="Permalink to &quot;症状 → 证据 → 处理 → 完成标准&quot;">​</a></h3><p><strong>症状</strong>：用户反馈&quot;等很久才出第一个字&quot;，出来之后流畅。 <strong>证据</strong>：流式埋点拆开 TTFT 与 ITL；prompt token 分布与缓存命中字段。 <strong>处理</strong>：按 <a href="./inference-fundamentals.html">推理基础</a> 的 TTFT runbook 排查排队 / prefill / 缓存失效。 <strong>完成标准</strong>：TTFT p50/p95 回到基线，能指着数据说出慢在哪一段。</p><h3 id="症状-→-证据-→-处理-→-完成标准-1" tabindex="-1">症状 → 证据 → 处理 → 完成标准 <a class="header-anchor" href="#症状-→-证据-→-处理-→-完成标准-1" aria-label="Permalink to &quot;症状 → 证据 → 处理 → 完成标准&quot;">​</a></h3><p><strong>症状</strong>：账单突增，调用量没涨。 <strong>证据</strong>：每轮 input tokens 随轮次线性膨胀；命中率下跌。 <strong>处理</strong>：按 <a href="./efficient-serving.html">高效服务</a> 与 <a href="./../03-context/session-memory.html">会话与状态</a> 修缓存友好结构与历史裁剪。 <strong>完成标准</strong>：单会话成本斜率回落，命中率回到基线。</p><h3 id="症状-→-证据-→-处理-→-完成标准-2" tabindex="-1">症状 → 证据 → 处理 → 完成标准 <a class="header-anchor" href="#症状-→-证据-→-处理-→-完成标准-2" aria-label="Permalink to &quot;症状 → 证据 → 处理 → 完成标准&quot;">​</a></h3><p><strong>症状</strong>：功能演示一切正常，上线后偶发失败。 <strong>证据</strong>：失败样本的 HTTP 状态码分布；429/5xx 占比。 <strong>处理</strong>：按 <a href="./model-api.html">模型 API 契约</a> 补错误族分类与退避重试；配额类错误先修配额。 <strong>完成标准</strong>：同样的流量下重试收敛、无未分类错误。</p><h2 id="_5-资料库" tabindex="-1">5. 资料库 <a class="header-anchor" href="#_5-资料库" aria-label="Permalink to &quot;5. 资料库&quot;">​</a></h2><h3 id="四级阅读路线" tabindex="-1">四级阅读路线 <a class="header-anchor" href="#四级阅读路线" aria-label="Permalink to &quot;四级阅读路线&quot;">​</a></h3><ul><li><strong>Beginner</strong>：<a href="./inference-fundamentals.html">推理基础</a>（跑通模拟器）→ <a href="./model-api.html">模型 API 契约</a>（发出第一条调用）。</li><li><strong>Builder</strong>：<a href="./efficient-serving.html">高效服务</a> → <a href="./structured-output.html">结构化输出</a> → <a href="./streaming.html">流式响应</a>。</li><li><strong>Operator</strong>：各主题&quot;开发&quot;段的 runbook → <a href="./../08-production/observability.html">可观测性</a>、<a href="./../08-production/cost-performance.html">成本与性能</a>。</li><li><strong>Researcher</strong>：<a href="./ui.html">生成式 UI</a> → <a href="./browser-edge.html">浏览器与端侧推理</a> → 组内资源表指向的论文与引擎文档（FlashAttention、vLLM）。</li></ul><h3 id="主动证伪与未决问题" tabindex="-1">主动证伪与未决问题 <a class="header-anchor" href="#主动证伪与未决问题" aria-label="Permalink to &quot;主动证伪与未决问题&quot;">​</a></h3><ul><li>本组断言&quot;感知延迟由 TTFT 主导&quot;来自流式传输的通用工程经验，具体产品的阈值需自行度量。</li><li>组内两页 fixture 的成本单位与单价是教学常数，验证的是结构与归因方法，不是任何厂商的真实数字。</li><li>厂商字段名、缓存档位与错误码随版本变化，本组表格只保留已核验版本，以官方文档为准。</li></ul><h3 id="learn-ai-到此为止-继续去哪" tabindex="-1">learn-ai 到此为止 / 继续去哪 <a class="header-anchor" href="#learn-ai-到此为止-继续去哪" aria-label="Permalink to &quot;learn-ai 到此为止 / 继续去哪&quot;">​</a></h3><p>本组回答&quot;怎么把模型变成在线服务与接口&quot;，不回答&quot;模型这一轮看到什么&quot;（→ <a href="./../03-context/session-memory.html">组 3 · 上下文</a>）、&quot;如何引入参数之外的知识&quot;（→ <a href="./../04-grounding/rag.html">嵌入与检索</a>）、&quot;如何受控执行动作&quot;（→ <a href="./../05-action/tool-calling.html">工具调用契约</a>）、&quot;上线证据&quot;（→ <a href="./../08-production/observability.html">可观测性</a>）。</p>`,34))])}const _=o(u,[["render",p]]);export{T as __pageData,_ as default};
